// Migração 349: análise de adulteração dos arquivos dos documentos da homologação (aba Adulteração da Gestão de Arquivos).
// adulteracao = lista do registro; adulteracao_analisar = pede a análise de um arquivo; adulteracao_ciente = ciência com o motivo
// (libera a aprovação do documento com risco alto). Pedir e registrar ciência exigem Editar na Portaria ou na Gestão de Fornecedores/
// Funcionários. Fornecedor externo não vê a análise.
if(in_array($action,['adulteracao','adulteracao_analisar','adulteracao_ciente'],true)){
    require_once dirname(__DIR__, 2) . '/classes/HomologacaoDocumentoAdulteracao.php';
    require_once dirname(__DIR__, 2) . '/classes/HomologacaoFornecedorAcesso.php';
    $tAd=static fn(string $c,array $p):string=>IdiomaService::t('api.arquivos.adulteracao.'.$c,$p);
    $escopoAd=HomologacaoDocumentoAdulteracao::TIPO_GED[$type]??null;
    if($escopoAd===null||!HomologacaoDocumentoAdulteracao::disponivel($tenant))$json(['ok'=>true,'disponivel'=>false,'analises'=>[]]);
    if(HomologacaoFornecedorAcesso::externo())$json(['ok'=>false,'message'=>$tAd('externo',['pt'=>'A análise de adulteração é só da empresa.','en'=>'The tampering analysis is for the company only.','es'=>'El análisis de adulteración es solo de la empresa.'])],403);
    $podeAd=false;foreach($type==='fornecedorcriterios'?['PORTARIA_DOCUMENTACAO_FORNECEDOR','HOMOLOGACAO_FORNECEDOR_FORNECEDOR']:['PORTARIA_DOCUMENTACAO_FUNCIONARIO','HOMOLOGACAO_FORNECEDOR_FUNCIONARIO'] as $telaAd)if(!empty(PermissaoTransacao::obter($telaAd)['pode_editar']))$podeAd=true;
    $usuarioAd=(int)($_SESSION['usuario']['codusuario']??0);
    $listarAd=static function()use($tenant,$escopoAd,$id):array{$q=$tenant->prepare('CALL sp_doc_adult_listar(?,?)');$q->execute([$escopoAd,$id]);$l=$q->fetchAll(PDO::FETCH_ASSOC);$q->closeCursor();foreach($l as &$r){$r['INDICIOS']=json_decode((string)($r['INDICIOS']??''),true)?:[];$locais=json_decode((string)($r['LOCAIS']??''),true)?:[];$r['TECNICO']=$locais['tecnico']??[];unset($r['LOCAIS'],$r['HASH']);}unset($r);return $l;};
    if($action!=='adulteracao'){
        if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$json(['ok'=>false,'message'=>IdiomaService::t('api.token_invalido',['pt'=>'Token de segurança inválido. Recarregue a página e tente novamente.','en'=>'Invalid security token. Reload the page and try again.','es'=>'Token de seguridad inválido. Recargue la página e inténtelo nuevamente.'])],419);
        if(!$podeAd)$json(['ok'=>false,'message'=>$tAd('sem_permissao',['pt'=>'Seu perfil não pode pedir a análise nem registrar ciência (Segurança › Permissões › Documentação de Fornecedor/Funcionário › Editar).','en'=>'Your profile cannot request the analysis or record acknowledgment (Security › Permissions › Supplier/Employee Documentation › Edit).','es'=>'Su perfil no puede pedir el análisis ni registrar conocimiento (Seguridad › Permisos › Documentación de Proveedor/Empleado › Editar).'])],403);
        if($action==='adulteracao_analisar'){
            $nomeAd=basename((string)($_POST['arquivo']??''));$fileAd=$storage->resolve($cfg['folder'],$folderId,$nomeAd);
            if($fileAd===null)$json(['ok'=>false,'message'=>IdiomaService::t('api.arquivos.nao_encontrado',['pt'=>'Arquivo não encontrado.','en'=>'File not found.','es'=>'Archivo no encontrado.'])],404);
            try{$rAd=HomologacaoDocumentoAdulteracao::pedirManual($tenant,$env,(string)($_SESSION['tenant']['banco_dados']??''),$escopoAd,$id,$fileAd,$usuarioAd);}catch(Throwable $e){$json(['ok'=>false,'message'=>$e->getMessage()],400);}
            $audit('ADULTERACAO_ANALISAR',['arquivo'=>$nomeAd,'codanalise'=>$rAd['codanalise']]);
            $json(['ok'=>true,'novo'=>$rAd['novo'],'codanalise'=>$rAd['codanalise'],'analises'=>$listarAd(),'message'=>$rAd['novo']?$tAd('pedido',['pt'=>'Pedido registrado: o serviço lê o arquivo e faz a análise em alguns minutos.','en'=>'Request recorded: the service reads the file and runs the analysis in a few minutes.','es'=>'Pedido registrado: el servicio lee el archivo y hace el análisis en algunos minutos.']):$tAd('ja_existe',['pt'=>'Este arquivo já foi analisado (ou está na fila).','en'=>'This file was already analyzed (or is queued).','es'=>'Este archivo ya fue analizado (o está en la cola).'])]);
        }
        $codAd=(int)($_POST['codanalise']??0);$doRegistro=false;foreach($listarAd() as $rAd)if((int)$rAd['CODANALISE']===$codAd)$doRegistro=true;
        if(!$doRegistro)$json(['ok'=>false,'message'=>$tAd('nao_localizada',['pt'=>'Análise não localizada neste documento.','en'=>'Analysis not found for this document.','es'=>'Análisis no encontrado en este documento.'])],404);
        try{$q=$tenant->prepare('CALL sp_doc_adult_ciente(?,?,?)');$q->execute([$codAd,$usuarioAd,(string)($_POST['motivo']??'')]);$q->fetchAll();$q->closeCursor();}catch(PDOException $e){$msgAd=(string)($e->errorInfo[2]??$e->getMessage());$json(['ok'=>false,'message'=>$msgAd],400);}
        $audit('ADULTERACAO_CIENCIA',['codanalise'=>$codAd]);
        $json(['ok'=>true,'analises'=>$listarAd(),'message'=>$tAd('ciente',['pt'=>'Ciência registrada: o documento pode ser aprovado.','en'=>'Acknowledgment recorded: the document can be approved.','es'=>'Conocimiento registrado: el documento puede ser aprobado.'])]);
    }
    $json(['ok'=>true,'disponivel'=>true,'pode_ciencia'=>$podeAd,'analises'=>$listarAd()]);
}
// Prévia do visualizador (Office, TIFF, planilhas, DWG/DXF). A tela não converte nada: previa_estado consulta o cache e,
// se ainda não houver, pede a conversão na fila do banco universal (sp_visualizador_pedir); o serviço
// scripts/visualizador-worker.php (Agendador do Windows, a cada minuto) converte. previa entrega o resultado do cache.
if($action==='previa_estado'||$action==='previa'){
    $nomeArquivo=basename((string)($_GET['arquivo']??''));
    if($ehDono($nomeArquivo))$podeBaixar=true;
    $file=$storage->resolve($cfg['folder'],$folderId,$nomeArquivo);
    if($file===null)$json(['ok'=>false,'message'=>IdiomaService::t('api.arquivos.nao_encontrado', ['pt' => 'Arquivo não encontrado.', 'en' => 'File not found.', 'es' => 'Archivo no encontrado.'])],404);
    $ext=strtolower(pathinfo($file,PATHINFO_EXTENSION)); $alvo=VisualizadorPrevia::alvo($ext);
    if($alvo===null)$json(['ok'=>false,'message'=>IdiomaService::t('api.arquivos.sem_previa', ['pt' => 'Este formato não tem prévia no sistema.', 'en' => 'This format has no preview.', 'es' => 'Este formato no tiene vista previa.'])],400);
    $chavePrevia=VisualizadorPrevia::chave($file,$alvo); $pronto=VisualizadorPrevia::cachePronto($chavePrevia,$alvo);
    if($action==='previa'){
        if($pronto===null)$json(['ok'=>false,'message'=>IdiomaService::t('api.arquivos.previa_pendente', ['pt' => 'A prévia ainda não está pronta.', 'en' => 'The preview is not ready yet.', 'es' => 'La vista previa aún no está lista.'])],404);
        $destino=strtolower((string)($_SERVER['HTTP_SEC_FETCH_DEST']??''));
        if(!$podeBaixar&&in_array($destino,['document','iframe','frame','embed','object'],true)){$q=$_GET;$q['action']='visualizar';header('Location: ../visualizador_arquivo.php?u='.rawurlencode('api/gestao_arquivos.php?'.http_build_query($q)),true,302);exit;}
        $audit('VISUALIZAR',['arquivo'=>basename($file),'previa'=>$alvo,'pasta_codlicenca'=>$folderId]);
        VisualizadorPrevia::enviar($pronto,$alvo==='pdf'?'application/pdf':'text/html','inline',pathinfo($file,PATHINFO_FILENAME).'.'.$alvo,$alvo==='html');
    }
    $urlPrevia=$base.'&arquivo='.rawurlencode($nomeArquivo).'&action=previa'.($type==='licencas'&&$unit>0?'&CODUNIDADE='.$unit:'');
    if($pronto!==null)$json(['ok'=>true,'pronto'=>true,'alvo'=>$alvo,'url'=>$urlPrevia]);
    // Desenho com PDF de mesmo nome no GED (o PDF "oficial" do projeto): mostra esse PDF em vez da prévia gerada
    if(in_array($ext,VisualizadorPrevia::CAD,true)){
        $nomeBase=pathinfo($nomeArquivo,PATHINFO_FILENAME);
        foreach([$nomeBase.'.pdf',$nomeBase.'.PDF'] as $pdfIrmao){if($storage->resolve($cfg['folder'],$folderId,$pdfIrmao)!==null)$json(['ok'=>true,'pronto'=>true,'alvo'=>'pdf','original'=>true,'arquivo_pdf'=>$pdfIrmao,'url'=>$base.'&arquivo='.rawurlencode($pdfIrmao).'&action=visualizar'.($type==='licencas'&&$unit>0?'&CODUNIDADE='.$unit:'')]);}
    }
    try{
        $universal=GreenPortalDatabase::connect($env,(string)($env['GUNIVERSAL_DB_DATABASE']??'guniversal_dbp'),'GUNIVERSAL');
        $pedido=GreenPortalDatabase::call($universal,'CALL sp_visualizador_pedir(?,?,?,?,?,?)',[$chavePrevia,realpath($file)?:$file,$ext,$alvo,(string)($_SESSION['tenant']['banco_dados']??''),(int)($_SESSION['usuario']['codusuario']??0)])[0]??[];
    }catch(Throwable $e){error_log('visualizador: '.$e->getMessage());$json(['ok'=>false,'pronto'=>false,'message'=>IdiomaService::t('api.arquivos.previa_indisponivel', ['pt' => 'A conversão de arquivos ainda não está disponível (migração 287).', 'en' => 'File conversion is not available yet (migration 287).', 'es' => 'La conversión de archivos aún no está disponible (migración 287).'])],503);}
    // O serviço pode ter terminado entre a consulta ao cache e o pedido
    if(($pedido['status']??'')==='CONCLUIDO'&&VisualizadorPrevia::cachePronto($chavePrevia,$alvo)!==null)$json(['ok'=>true,'pronto'=>true,'alvo'=>$alvo,'url'=>$urlPrevia]);
    $json(['ok'=>true,'pronto'=>false,'alvo'=>$alvo,'status'=>(string)($pedido['status']??'PENDENTE'),'erro'=>($pedido['status']??'')==='ERRO'?(string)($pedido['erro']??''):null,'tentativas'=>(int)($pedido['tentativas']??0),'espera'=>(int)($pedido['espera_segundos']??0),'na_frente'=>(int)($pedido['na_frente']??0)]);
}
// Visualizar / baixar um arquivo. Sem "Baixar/imprimir arquivos": abrir o arquivo direto no navegador (aba, iframe) leva ao
// visualizador do sistema, sem Salvar nem Imprimir; o conteúdo só é entregue ao visualizador (PDF.js) e às imagens da tela;
